import datetime
import glob
import os
import xml.etree.ElementTree as ElementTree
from collections import OrderedDict
from functools import partial

from lxml import objectify

from ..exception import (
    ConfigParameterError,
    DirectoryError,
    LuaConfigGenError,
    MultipleScfcAreFound,
    ScfcNotFound,
    SSHCommandError,
)
from ..ssh import SshConnectionAdapter
from ..utils.settings import ConnectionSettings

LUA_CONFIG = OrderedDict(
    [
        ("edaemon_ip", '"127.0.0.1"'),
        ("edaemon_port", '"10000"'),
        ("s1_ip", '"10.0.1.1"'),
        ("pgw_net_part", '"1.7"'),
        ("pgw_ip", '"1.7.255.254/16"'),
        ("s1u_port", '"2152"'),
        ("s11_port", '"2153"'),
        ("mme_port", '"36412"'),
        ("mmegi", '"1"'),
        ("mmec", '"3"'),
        ("uec_ip", '"11.7.255.254/16"'),
        ("uec_net_part", '"11.7"'),
        ("uec_server_ip", '"10.0.2.1"'),
        ("uec_proxy_ip", '"10.0.2.2"'),
        ("uec_proxy_port", '"2152"'),
        ("plmn", ""),
        ("enb_s1_ip", ""),
        ("enb_macro_id", ""),
        ("cells", ""),
        ("tac", ""),
        ("ue_count_per_cell", "100"),
        ("sec_key", '"0102030405060708090A0B0C0D0E"'),
        ("sec_op_key", '"ABCDEF0123456789ABCDEF0123456789"'),
        ("imsi_prefix", '"666:652:40500"'),
    ]
)


class LuaConfigGenerator:
    """Class was created to build lua configuration file based on SCFC.xml and config template.
    Class supports multi eNBs functionality.

    """

    def __init__(
        self,
        ssh_client: SshConnectionAdapter,
        connection_settings: ConnectionSettings,
    ):
        """
        :param list of ssh_client:                         SSH clients with established SSH sessions.
        :param ConnectionSettings connection_settings:     SSH Connection Settings for remote host connection
        """
        self._ssh_client = ssh_client
        self._lua_config = LUA_CONFIG.copy()
        self._scfc_xml = None
        self._iphy_xml = None
        self._config_dir_path = None
        self._config_file_name = None
        self._iphy_path = None
        self._connection_settings = connection_settings

    def build_configuration(
        self,
        config_dir: str,
        config_file: str,
        scf_dir: str,
        enb_index: int = 1,
        iphy_path: str | None = None,
        **kwargs,
    ) -> None:
        """
        Method updates configuration parameters values in template according to SCFC file and
        passed arguments (if exists). Updated template is written into config file and lua path
        is extended.

        :param string config_dir:       Path to lua configuration directory.
        :param string config_file:      Lua configuration file name.
        :param string scf_dir:          Path to scf template directory.
        :param integer enb_index:       Indicates index of line in multi-enb environment.
        :param string iphy_path:        Path to iphy xml configuration file.

        |

        :Customized parameters are available via kwargs (example below):
            * **edaemon_ip**    (string)    - IP address, where edaemon is running.
            * **tac**           (string)    - Tac parameter.
            * **cells**         (string)    - Cell IDs (example cells={1, 2, 3}.
            * **mme_port**      (string)    - MME port parameter.

        """
        self._iphy_path = iphy_path
        self._config_dir_path = self._norm_dir_path(config_dir)
        self._config_file_name = self._norm_file_name(config_file)

        self._scfc_xml = self._get_scfc_xml(scf_dir)

        self._lua_config["plmn"] = self._get_plmn_value()
        self._lua_config["tac"] = self._get_tac_value()
        self._lua_config["enb_s1_ip"] = f'"10.0.1.{enb_index * 2}"'
        self._set_enb_s1_ip_values()
        self._lua_config["enb_macro_id"] = self._get_enb_macro_id_value()
        self._lua_config["cells"] = self._get_cells_id_value()
        self._lua_config["uec_server_ip"] = self._get_uec_server_ip_value(enb_index - 1)
        self._lua_config["uec_proxy_ip"] = self._get_uec_proxy_ip_value(enb_index - 1)

        if iphy_path:
            self._compose_supercell_configuration()

        self._set_custom_param(**kwargs)

        self._build_config_file()
        self._extend_lua_path()

    def _norm_dir_path(self, directory_path: str) -> str:
        if not os.path.exists(directory_path):
            raise DirectoryError("Dictionary %s does not exist" % directory_path)
        else:
            return os.path.normpath(directory_path)

    def _norm_file_name(self, config_file_name: str) -> str:
        name, extension = os.path.splitext(config_file_name)
        return config_file_name if extension == ".lua" else f"{config_file_name}.lua"

    def _get_plmn_value(self) -> str:
        mcc = self._scfc_xml.xpath(
            './/ns:managedObject[@class="LNBTS"]/ns:p[@name="mcc"]/text()',
            namespaces={"ns": "raml21.xsd"},
        )
        if not mcc:
            mcc = self._scfc_xml.xpath(
                './/ns:managedObject[@class="NOKLTE:LNBTS"]/ns:p[@name="mcc"]/text()',
                namespaces={"ns": "raml21.xsd"},
            )

        mnc = self._scfc_xml.xpath(
            './/ns:managedObject[@class="LNBTS"]/ns:p[@name="mnc"]/text()',
            namespaces={"ns": "raml21.xsd"},
        )
        if not mnc:
            mnc = self._scfc_xml.xpath(
                './/ns:managedObject[@class="NOKLTE:LNBTS"]/ns:p[@name="mnc"]/text()',
                namespaces={"ns": "raml21.xsd"},
            )

        return '"%d:%02d"' % (int(mcc[0]), int(mnc[0]))

    def _get_tac_value(self) -> str:
        tac = self._scfc_xml.xpath(
            './/ns:managedObject[@class="LNCEL"]/ns:p[@name="tac"]/text()',
            namespaces={"ns": "raml21.xsd"},
        )
        if not tac:
            tac = self._scfc_xml.xpath(
                './/ns:managedObject[@class="NOKLTE:LNCEL"]/ns:p[@name="tac"]/text()',
                namespaces={"ns": "raml21.xsd"},
            )
        return f'"{tac[0]}"'

    def _set_enb_s1_ip_values(self) -> None:
        try:
            self._set_ip_values_from_config()
        except SSHCommandError:
            self._set_enb_s1_ip_via_scfc()

    def _set_ip_values_from_config(self) -> None:
        self._execute_cmd_on_enb(cmd="(/opt/trs/bin/objcli generate_scf)")
        self._set_ip_value_from_config("enb_s1_ip", "localIpAddr")
        self._set_ip_value_from_config("enb_c_s1_ip", "cPlaneIpAddress")
        self._set_ip_value_from_config("enb_m_s1_ip", "mPlaneIpAddress")

    def _set_enb_s1_ip_via_scfc(self) -> None:
        enb_s1_ip_list = self._scfc_xml.xpath(
            './/ns:managedObject[@class="com.nokia.srbts.tnl:IPADDRESSV4"]/ns:p[@name="localIpAddr"]/text()',
            namespaces={"ns": "raml21.xsd"},
        )
        if enb_s1_ip_list:
            self._lua_config["enb_s1_ip"] = f'"{enb_s1_ip_list[0]}"'

    def _set_ip_value_from_config(
        self, ip_to_be_set: str, ip_name_in_config: str
    ) -> None:
        result = self._get_ip_from_config(ip_name_in_config)
        if result:
            self._lua_config[ip_to_be_set] = f'"{result}"'

    def _get_ip_from_config(self, ip_name_in_config: str) -> str:
        cmd = rf'grep -w "{ip_name_in_config}" /tmp/transport/ftp/config.xml | grep -oE "([0-9]+\.){{3}}[0-9]+"'
        result = self._execute_cmd_on_enb(cmd=cmd)
        return result

    def _get_enb_macro_id_value(self) -> str:
        xpath_result = self._scfc_xml.xpath(
            './/ns:managedObject[@class="BTSSCL"]/ns:p[@name="btsId"]/text()',
            namespaces={"ns": "raml21.xsd"},
        )
        if not xpath_result:
            xpath_result = self._scfc_xml.xpath(
                './/ns:managedObject[@class="MRBTS"]/@distName',
                namespaces={"ns": "raml21.xsd"},
            )
            if not xpath_result:
                xpath_result = self._scfc_xml.xpath(
                    './/ns:managedObject[contains(@class, "MRBTS")]/@distName',
                    namespaces={"ns": "raml21.xsd"},
                )
            xpath_result[0] = xpath_result[0].split("-")[1]
        return f'"{int(xpath_result[0]):#07x}"'

    def _get_cells_id_value(self) -> str:
        dist_names = self._get_distname_cells_in_order()
        cell_ids = self._get_cell_ids_value_in_order(dist_names)
        return self._list2string(cell_ids)

    def _get_distname_cells_in_order(self) -> list:
        dist_name_cells = self._scfc_xml.xpath(
            './/ns:managedObject[@class="LNCEL"]/@distName',
            namespaces={"ns": "raml21.xsd"},
        )
        if not dist_name_cells:
            dist_name_cells = self._scfc_xml.xpath(
                './/ns:managedObject[@class="NOKLTE:LNCEL"]/@distName',
                namespaces={"ns": "raml21.xsd"},
            )
        return sorted(dist_name_cells)

    def _get_cell_ids_value_in_order(self, distnames: list[str]) -> list:
        xpaths = self._scfc_xml.xpath(
            './/ns:managedObject[@class="LNCEL"]', namespaces={"ns": "raml21.xsd"}
        )
        if xpaths:
            xpaths = map(
                './/ns:managedObject[@class="LNCEL" and @distName="{}"]/ns:p[@name="phyCellId"]/text()'.format,
                distnames,
            )
        else:
            xpaths = map(
                './/ns:managedObject[@class="NOKLTE:LNCEL" and @distName="{}"]/ns:p[@name="phyCellId"]/text()'.format,
                distnames,
            )

        get_cell_id_via_dist_name = partial(
            self._scfc_xml.xpath, namespaces={"ns": "raml21.xsd"}
        )
        return map(get_cell_id_via_dist_name, xpaths)

    def _get_uec_server_ip_value(self, line_index: int) -> str:
        return f'"10.0.2.{2 * line_index + 1}"'

    def _get_uec_proxy_ip_value(self, line_index: int) -> str:
        return f'"10.0.2.{2 * line_index + 2}"'

    def _set_custom_param(self, **kwargs) -> None:
        for key, value in kwargs.items():
            config_parameter = f"{key}"
            if config_parameter in self._lua_config:
                self._lua_config[config_parameter] = f'"{value}"'
            else:
                raise ConfigParameterError(
                    "%s is not valid configuration parameter" % key
                )

    def _execute_cmd_on_enb(self, cmd: str) -> str:
        out, err, rc = self._ssh_client.execute_command(cmd)
        out = out.strip()
        err = err.strip()
        if err == "" and rc == 0:
            return out
        else:
            raise SSHCommandError(err)

    def _extend_lua_path(self) -> None:
        command = f'export LUA_PATH="{self._config_dir_path}/?.lua;$LUA_PATH"'
        if os.system(command):
            raise LuaConfigGenError("Lua path extention failed")

    def _build_config_file(self) -> None:
        module_name = os.path.splitext(self._config_file_name)[0]
        with open(
            os.path.join(self._config_dir_path, self._config_file_name), "w"
        ) as f:
            f.write(self._make_headline_comments())
            f.write(f'module("{module_name}",package.seeall)\n')
            for lua_config_key, lua_config_value in self._lua_config.items():
                f.write(f"{module_name}.{lua_config_key} = {lua_config_value}\n")

    def _compose_supercell_configuration(self) -> None:
        self._iphy_xml = self._read_iphy()
        for group in self._get_unique_group():
            cell = [
                cell_group[1]
                for cell_group in self._get_cell_and_group()
                if cell_group[0] == group
            ]
            subcell = self._create_dynamic_subcell(*cell)
            self._lua_config[f"cell_group{group}"] = f"'enb=1 group={group}{subcell}'"

    def _create_dynamic_subcell(self, *subcells) -> str:
        subcell_list = [f" subcell={subcell}" for subcell in subcells]
        return "".join(subcell_list)

    def _get_unique_group(self) -> list[int]:
        return list({i[0] for i in self._get_cell_and_group()})

    def _get_scfc_xml(self, scf_dir: str) -> ElementTree:
        paths = glob.glob(f"{scf_dir}/*.xml")
        if paths:
            if not self._is_only_one_file(paths):
                raise MultipleScfcAreFound("More than one scfc file is found")
        else:
            raise ScfcNotFound("No scfc file is found")
        return self._read_scfc(paths[0])

    def _get_antenna_attribute(self, child_node: str) -> list[int]:
        antenna = (
            self._iphy_xml.findall(
                f"./OBSAI-Config/RRH_List/RRH/hardware/antennaList/antenna/{child_node}"
            )
            or self._iphy_xml.findall(
                f"./CPRI-Config/CMCC-RE_List/RE/hardware/axcList/axc/{child_node}"
            )
            or self._iphy_xml.findall(
                f"./CPRI-Config/DCM-RE_List/RE/hardware/axcList/axc/{child_node}"
            )
        )
        return [int(info.text) for info in antenna]

    def _get_cell_and_group(self) -> list[int]:
        cell_and_group = list(
            zip(
                self._get_antenna_attribute("group"),
                self._get_antenna_attribute("cell"),
            )
        )
        return [cell_and_group[index - 1] for index in range(1, len(cell_and_group), 2)]

    def _change_paths_format_to_list_of_tuples(self, src_dst_path: list) -> list:
        """Keeps backward compatibility of SSHLibrary outputs"""
        return list(zip(*src_dst_path)) if type(src_dst_path) is tuple else src_dst_path

    def _read_scfc(self, scfc_path: str) -> ElementTree:
        return objectify.parse(scfc_path)

    def _read_iphy(self) -> ElementTree:
        return ElementTree.parse(self._iphy_path)

    def _is_only_one_file(self, paths: list[str]) -> bool:
        return True if len(paths) == 1 else False

    def _list2string(self, param_list: list) -> str:
        param_str = ",".join([param[0] for param in param_list])
        return f"{{{param_str}}}"

    def _make_headline_comments(self) -> str:
        content = (
            "-- *****************************************************************\n"
            "-- Testline variables\n"
            f"-- (generated on {self._date} {self._time} by ute_wtssim library)\n"
            "-- *****************************************************************\n"
        )
        return content

    @property
    def _date(self) -> str:
        return datetime.datetime.now().strftime("%y-%m-%d")

    @property
    def _time(self) -> str:
        return datetime.datetime.now().strftime("%H:%M:%S")
